mkdir -p /tmp/preview-check && cat > /tmp/preview-check/main_test.go <<'EOF'
package main

import (
	"fmt"
	"testing"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

func TestScratch(t *testing.T) {
	reg := stowage.NewRegistry()
	reg.RegisterCompartment("A", 30)
	reg.RegisterCompartment("B", 30)
	reg.RegisterCargo("C1", 30, "上海", false)
	reg.RegisterCargo("C2", 30, "上海", false)
	if _, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "C1", Target: "A"},
		{Kind: stowage.OpLoad, CargoID: "C2", Target: "B"},
	}); err != nil {
		t.Fatal(err)
	}

	swap := []stowage.Op{
		{Kind: stowage.OpMove, CargoID: "C1", Target: "B"},
		{Kind: stowage.OpMove, CargoID: "C2", Target: "A"},
	}
	p, err := reg.Preview(swap)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("Submittable=%v rejections=%d\n", p.Submittable, len(p.Rejections))
	for _, c := range p.CargoChanges {
		fmt.Printf("cargo %s: %q -> %q\n", c.CargoID, c.From, c.To)
	}
	for _, cp := range p.Compartments {
		fmt.Printf("comp %s before used=%d remain=%d cargo=%v\n", cp.ID, cp.Before.UsedWeight, cp.Before.RemainingWeight, ids(cp.Before.Cargo))
		for _, cv := range cp.After.Cargo {
			fmt.Printf("comp %s after cargo %s loaded=%v comp=%q\n", cp.ID, cv.ID, cv.Loaded, cv.CompartmentID)
		}
		fmt.Printf("comp %s after used=%d remain=%d\n", cp.ID, cp.After.UsedWeight, cp.After.RemainingWeight)
	}
	// 预览后查询仍是交换前位置
	cv, _ := reg.Cargo("C1")
	fmt.Printf("after preview, C1 at %q\n", cv.CompartmentID)

	// 第三件货物
	reg.RegisterCargo("C3", 10, "广州", true)
	p2, err := reg.Preview([]stowage.Op{{Kind: stowage.OpLoad, CargoID: "C3", Target: "A"}})
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("p2 Submittable=%v comps=%d\n", p2.Submittable, len(p2.Compartments))
	for _, r := range p2.Rejections {
		fmt.Printf("rej comp=%s kind=%v max=%d used=%d remain=%d over=%d dests=%+v offenders=%v\n",
			r.CompartmentID, r.Kind, r.MaxWeight, r.UsedWeight, r.RemainingWeight, r.Overweight, r.Destinations, r.OffendingCargo)
	}
	fmt.Printf("p2 cargoChanges=%+v\n", p2.CargoChanges)
	for _, cp := range p2.Compartments {
		fmt.Printf("p2 comp %s after used=%d remain=%d cargo=%v\n", cp.ID, cp.After.UsedWeight, cp.After.RemainingWeight, ids(cp.After.Cargo))
	}

	// 不存在的货物
	p3, err := reg.Preview([]stowage.Op{{Kind: stowage.OpMove, CargoID: "C9", Target: "A"}})
	fmt.Printf("p3 result=%v err=%v\n", p3, err)
	if se, ok := err.(*stowage.Error); ok {
		fmt.Printf("kind=%v id=%q adj=%q\n", se.Kind, se.ID, se.AdjustmentID)
	}

	// 正式提交交换
	res, err := reg.Adjust("swap-1", swap)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("adjust result=%+v\n", res.CargoChanges)
	cv, _ = reg.Cargo("C1")
	fmt.Printf("after commit, C1 at %q\n", cv.CompartmentID)
}

func ids(vs []stowage.CargoView) []string {
	out := []string{}
	for _, v := range vs {
		out = append(out, v.ID)
	}
	return out
}
EOF
